let tmdbCredential='',tmdbResults=[],tmdbPage=1,tmdbQuery='',tmdbType='tv',tmdbBusy=false;
try{tmdbCredential=AppStorage.getItem('anishelf-tmdb-credential')||''}catch{}
const tmdbDialog=$('#addDialog');$('#onlineAddPanel').innerHTML=ui`<div id="tmdbSetupHint" class="tmdb-setup-hint">请先在设置中配置 TMDb。<button id="goTmdbSettings">前往设置 ↗</button></div><form id="tmdbSearchForm" class="tmdb-search"><input id="tmdbQuery" required maxlength="120" placeholder="例如：葬送的芙莉莲" aria-label="动漫名称"><select id="tmdbType" aria-label="作品类型"><option value="tv">动画剧集</option><option value="movie">动画电影</option></select><button class="primary" type="submit">搜索</button></form><div id="tmdbStatus" role="status">输入名称搜索动画。</div><div id="tmdbResults"></div><div class="tmdb-paging"><button id="tmdbPrevious" hidden>上一页</button><span id="tmdbPageLabel"></span><button id="tmdbNext" hidden>下一页</button></div><div class="tmdb-attribution"><a href="https://www.themoviedb.org" target="_blank" rel="noopener"><img src="https://www.themoviedb.org/assets/2/v4/logos/v2/blue_short-8e7b30f73a4020692ccca9c88bafe5dcb6f8a62a4c6bc55cd9ba82bb2cd95f6c.svg" alt="TMDB" width="64"></a><span>This product uses the TMDB API but is not endorsed or certified by TMDB.</span></div>`;
let rememberTmdb=!!tmdbCredential,tmdbConnectionState=tmdbCredential?t("已配置，待测试"):t("未配置"),tmdbSettingsMessage='',tmdbTesting=false;
function updateTmdbAvailability(){$('#tmdbSetupHint').hidden=!!tmdbCredential;$('#tmdbSearchForm button').disabled=tmdbBusy||!tmdbCredential;}
function useTmdbCredential(){tmdbCredential=$('#tmdbCredential').value.trim();rememberTmdb=$('#rememberTmdb').checked;tmdbConnectionState=tmdbCredential?t("已配置，待测试"):t("未配置");try{if(rememberTmdb&&tmdbCredential)AppStorage.setItem('anishelf-tmdb-credential',tmdbCredential);else AppStorage.removeItem('anishelf-tmdb-credential')}catch{toast(t("无法记住凭证，本次仍可使用"))}updateTmdbAvailability();return tmdbCredential}
function openTmdb(){openAddDialog('online');updateTmdbAvailability()}
$('#goTmdbSettings').onclick=()=>{$('#addDialog').close();page='settings';tag='';$('#search').value='';render();window.scrollTo({top:0,behavior:'smooth'});$('#tmdbCredential').focus()};
function bindTmdbSettings(){$('#tmdbCredential').value=tmdbCredential;$('#rememberTmdb').checked=rememberTmdb;$('#tmdbConnection').textContent=tmdbConnectionState;$('#tmdbSettingsStatus').textContent=tmdbSettingsMessage;$('#testTmdb').disabled=tmdbTesting;
 const saveSettings=()=>{useTmdbCredential();tmdbSettingsMessage=t("设置已保存");$('#tmdbConnection').textContent=tmdbConnectionState;$('#tmdbSettingsStatus').textContent=tmdbSettingsMessage};
 $('#saveTmdb').onclick=saveSettings;$('#rememberTmdb').onchange=saveSettings;$('#tmdbCredential').onchange=saveSettings;
 $('#clearTmdb').onclick=()=>{$('#tmdbCredential').value='';$('#rememberTmdb').checked=false;useTmdbCredential();tmdbSettingsMessage=t("凭证已清除");$('#tmdbConnection').textContent=tmdbConnectionState;$('#tmdbSettingsStatus').textContent=tmdbSettingsMessage};
 $('#testTmdb').onclick=async()=>{const key=useTmdbCredential();tmdbTesting=true;tmdbConnectionState=t("正在连接…");$('#testTmdb').disabled=true;$('#tmdbConnection').textContent=tmdbConnectionState;try{await TMDB.request('configuration',key);if(tmdbCredential===key){tmdbConnectionState=t("连接成功");tmdbSettingsMessage=t("可以使用在线搜索")}}catch(error){if(tmdbCredential===key){tmdbConnectionState=t("连接失败");tmdbSettingsMessage=error.message}}finally{tmdbTesting=false;if(page==='settings')render()}};
}
updateTmdbAvailability();
function renderTmdbResults(){
 $('#tmdbResults').innerHTML=tmdbResults.map(a=>{const owned=a.media_type==='movie'&&library.some(b=>b.tmdbId===a.id&&b.tmdbType===a.media_type);return ui`<article class="tmdb-result"><img src="${esc(safeImage(a.poster_path?'https://image.tmdb.org/t/p/w185'+a.poster_path:''))}" alt="${esc(a.name||a.title)}封面"><div><h3>${esc(a.name||a.title)}</h3><small>${esc((a.first_air_date||a.release_date||'').slice(0,4))} · ${a.media_type==='tv'?t("剧集"):t("电影")} · TMDb ${Number(a.vote_average||0).toFixed(1)}</small><p>${esc(a.overview||t("暂无中文简介"))}</p><button data-tmdb-add="${a.id}" ${owned?'disabled':''}>${owned?t("已在收藏"):a.media_type==='tv'?t("选择季度"):t("＋ 加入收藏")}</button></div></article>`}).join('');$$('#tmdbResults img').forEach(img=>img.onerror=()=>{img.onerror=null;img.src=placeholder});
}
async function searchTmdb(nextPage=1){if(tmdbBusy)return;if(!tmdbCredential){updateTmdbAvailability();$('#tmdbStatus').textContent=t("请先在设置中配置 TMDb");return;}tmdbBusy=true;$('#tmdbSearchForm button').disabled=true;$('#tmdbPrevious').disabled=true;$('#tmdbNext').disabled=true;$('#tmdbStatus').textContent=t("正在搜索 TMDb…");try{const data=await TMDB.request('search/'+tmdbType,tmdbCredential,{query:tmdbQuery,page:nextPage,include_adult:false});tmdbPage=nextPage;tmdbResults=TMDB.animationResults(data,tmdbType);renderTmdbResults();$('#tmdbStatus').textContent=tmdbResults.length?ui`本页 ${tmdbResults.length} 部动漫`:t("无匹配结果，请更换名称或翻页。");$('#tmdbPageLabel').textContent=I18n.getLanguage()==='en-US'?ui`Page ${tmdbPage} / ${Math.max(1,Math.min(data.total_pages||1,500))}`:ui`第 ${tmdbPage} / ${Math.max(1,Math.min(data.total_pages||1,500))} 页`;$('#tmdbPrevious').hidden=tmdbPage<=1;$('#tmdbNext').hidden=tmdbPage>=Math.min(data.total_pages||1,500)}catch(error){$('#tmdbStatus').textContent=error.message}finally{tmdbBusy=false;updateTmdbAvailability();$('#tmdbPrevious').disabled=false;$('#tmdbNext').disabled=false}}
$('#tmdbSearchForm').onsubmit=e=>{e.preventDefault();if(tmdbBusy)return;tmdbQuery=$('#tmdbQuery').value.trim();tmdbType=$('#tmdbType').value;if(tmdbQuery){tmdbResults=[];$('#tmdbResults').innerHTML='';$('#tmdbPrevious').hidden=true;$('#tmdbNext').hidden=true;$('#tmdbPageLabel').textContent='';searchTmdb(1)}};$('#tmdbPrevious').onclick=()=>searchTmdb(tmdbPage-1);$('#tmdbNext').onclick=()=>searchTmdb(tmdbPage+1);
$('#tmdbResults').onclick=async e=>{const button=e.target.closest('[data-tmdb-add]');if(!button)return;const result=tmdbResults.find(a=>a.id===Number(button.dataset.tmdbAdd));if(!result)return;if(result.media_type==='tv'){await SeasonManager.openSeries(result.id);return}if(library.some(a=>a.tmdbId===result.id&&a.tmdbType===result.media_type))return;button.disabled=true;button.textContent=t("导入中…");try{const data=await TMDB.request(result.media_type+'/'+result.id,tmdbCredential,{append_to_response:result.media_type==='movie'?'images,credits':'images,aggregate_credits',include_image_language:'zh,ja,en,null'});const a=TMDB.normalize(data,result.media_type);if(library.some(b=>b.tmdbId===a.tmdbId&&b.tmdbType===a.tmdbType)){renderTmdbResults();return}while(library.some(b=>b.id===a.id))a.id++;const next=[a,...library];AppStorage.setItem('anishelf-library-v1',JSON.stringify(next));library=next;render();renderTmdbResults();$('#tmdbStatus').textContent=ui`已收藏「${a.title}」${a.episodeCountUnknown?t("，集数未提供，暂记为 1 集"):''}。`;toast(t("动漫已导入"))}catch(error){button.disabled=false;button.textContent=t("＋ 加入收藏");$('#tmdbStatus').textContent=error.name==='QuotaExceededError'?t("本地存储空间不足，请先导出备份。"):error.message}};
function switchAddMode(mode){const online=mode==='online';$('#onlineAddPanel').hidden=!online;$('#offlineAddPanel').hidden=online;$('#onlineAddTab').classList.toggle('selected',online);$('#offlineAddTab').classList.toggle('selected',!online);$('#onlineAddTab').setAttribute('aria-selected',String(online));$('#offlineAddTab').setAttribute('aria-selected',String(!online));$('#onlineAddTab').tabIndex=online?0:-1;$('#offlineAddTab').tabIndex=online?-1:0;}
function openAddDialog(mode='online'){switchAddMode(mode);if(!$('#addDialog').open)$('#addDialog').showModal();}
$('#add').onclick=()=>openAddDialog();
$('#onlineAddTab').onclick=()=>switchAddMode('online');
$('#offlineAddTab').onclick=()=>switchAddMode('offline');
['onlineAddTab','offlineAddTab'].forEach(id=>$('#'+id).onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const mode=e.key==='Home'?'online':e.key==='End'?'offline':id==='onlineAddTab'?'offline':'online';switchAddMode(mode);$('#'+(mode==='online'?'onlineAddTab':'offlineAddTab')).focus();}});
switchAddMode('online');
const baseRenderSettings=renderSettings;renderSettings=function(){baseRenderSettings();const row=document.createElement('section');row.className='tmdb-settings-block';row.innerHTML=t("<div class=\"tmdb-settings-heading\"><h3>TMDb 连接设置</h3><span id=\"tmdbConnection\" role=\"status\"></span></div><label class=\"field-label\">API Key / Read Access Token<input id=\"tmdbCredential\" type=\"password\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"粘贴你的 TMDb 凭证\"></label><label class=\"remember-key\"><input type=\"checkbox\" id=\"rememberTmdb\">在此浏览器记住凭证（仅保存在本机）</label><div class=\"tmdb-config-actions\"><button id=\"saveTmdb\">保存设置</button><button id=\"testTmdb\">测试连接</button><button id=\"clearTmdb\">清除凭证</button><a href=\"https://www.themoviedb.org/settings/api\" target=\"_blank\" rel=\"noopener\">获取凭证 ↗</a></div><p id=\"tmdbSettingsStatus\" role=\"status\"></p>");$('#extraSection .settings-panel').prepend(row);bindTmdbSettings();const attribution=document.createElement('div');attribution.className='tmdb-attribution';attribution.innerHTML='<a href="https://www.themoviedb.org" target="_blank" rel="noopener"><img src="https://www.themoviedb.org/assets/2/v4/logos/v2/blue_short-8e7b30f73a4020692ccca9c88bafe5dcb6f8a62a4c6bc55cd9ba82bb2cd95f6c.svg" alt="TMDB" width="64"></a><span>This product uses the TMDB API but is not endorsed or certified by TMDB.</span>';$('#extraSection .settings-panel').append(attribution)};
